#!/usr/bin/env python3
# tools/board.py -- build the static leaderboard (site/index.html, site/receipts.json) from receipts/*.json.
# Only receipts that pass tools/validate.py are shown; the page states how many were left out.
#   board.py [OUT_DIR]       (default: site)
# INTERIM host glue (Python); Omega successor: the page generated by an omc-built program, the way
# aienos.com pages are rendered from seeded Omega (skill render-page-from-omega).
import glob, html, json, os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import receipt as R  # noqa: E402
import validate as V  # noqa: E402

BLOB = "https://github.com/%s/blob/main/" % R.REPO
CMD = "git clone https://github.com/%s && cd omega-gpu-bench && ./run" % R.REPO
E = html.escape


def best(rec):
    rates = [r["gbps"] for r in rec["results"] if r["verdict"] == "PASS" and r["gbps"]]
    return max(rates) if rates else None


def kernels(rec):
    cells = []
    for r in rec["results"]:
        ok = r["verdict"] in ("PASS", "NEG_DETECTED")
        sm = r["cubin"].split("_")[1]
        cells.append('<span class="%s" title="%s">%s %s %s</span>' % (
            "ok" if ok else "bad", E(r["error"] or "%s of %s words differ" % (r["mismatches"], r["checked"])),
            E(r["kind"]), E(sm), E(r["verdict"])))
    return " ".join(cells)


def main():
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, "site")
    c = V.Checker(ROOT, os.path.join(ROOT, "kernels", "SHA256SUMS"),
                  os.path.join(ROOT, "receipts", "imports.sha256"), False)
    good, rejected = [], []
    for path in sorted(glob.glob(os.path.join(ROOT, "receipts", "*.json"))):
        try:
            rec = json.load(open(path))
            errs = c.check(rec)
        except ValueError as x:
            errs = [str(x)]
        (rejected if errs else good).append((os.path.relpath(path, ROOT), rec if not errs else None))
    ran = [(p, r) for p, r in good if r["results"]]
    ran.sort(key=lambda pr: (pr[1]["origin"] != "kit-run", -(best(pr[1]) or 0), pr[1]["run"]["utc"]))
    rows = []
    for i, (p, r) in enumerate(ran, 1):
        m, g = r["machine"], best(r)
        origin = ("kit run, self-reported" if r["origin"] == "kit-run"
                  else "imported CloudKernels run (before the kit)")
        rows.append("<tr><td>%d</td><td>%s<br><small>sm_%s</small></td><td>%s<br><small>CUDA driver API %s</small></td>"
                    "<td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td><a href=\"%s\">%s</a></td></tr>" % (
                        i, E(m["gpu"]), E(m["cc"].replace(".", "")), E(m["driver_version"] or "?"),
                        E(str(m["cuda_driver_api"])), E(r["provider"]), E(origin), kernels(r),
                        ("%.1f GB/s<br><small>%.3f ms per launch</small>" % (
                            g, min(x["kernel_ms"] for x in r["results"] if x["gbps"] == g)) if g else "not timed"),
                        E(r["run"]["utc"][:10]), E(BLOB + p), E(r["receipt_sha256"][:12])))
    waiting = ["<li>%s (sm_%s), driver %s: %s</li>" % (E(r["machine"]["gpu"]), E(r["machine"]["cc"].replace(".", "")),
                                                     E(r["machine"]["driver_version"] or "?"), E(r["not_run"]))
               for p, r in good if not r["results"]]
    page = TEMPLATE.format(
        cmd=E(CMD), repo=E(R.REPO), path=E(R.PATH_LABEL), rows="\n".join(rows) or
        '<tr><td colspan="9">No receipts yet.</td></tr>',
        waiting=("<h2>Cards without a kernel yet</h2><ul>%s</ul>" % "".join(waiting)) if waiting else "",
        nvalid=len(good), nrej=len(rejected))
    os.makedirs(out, exist_ok=True)
    with open(os.path.join(out, "index.html"), "w") as f:
        f.write(page)
    with open(os.path.join(out, "receipts.json"), "w") as f:
        json.dump([r for _, r in good], f, indent=1, sort_keys=True)
    print("board: %d receipts shown, %d rejected -> %s" % (len(good), len(rejected), out))
    for p, _ in rejected:
        print("  rejected " + p)


TEMPLATE = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Omega GPU bench: bring your own NVIDIA GPU</title>
<style>
body{{font:15px/1.5 system-ui,sans-serif;max-width:72rem;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}}
code,pre{{font:13px ui-monospace,monospace;background:#f3f3f3;padding:.1rem .3rem;border-radius:3px}}
pre{{padding:.7rem;overflow-x:auto}} table{{border-collapse:collapse;width:100%;font-size:14px}}
th,td{{border-bottom:1px solid #ddd;padding:.45rem;text-align:left;vertical-align:top}} small{{color:#555}}
.ok{{color:#065f46;white-space:nowrap}} .bad{{color:#b91c1c;font-weight:600;white-space:nowrap}}
.note{{border-left:3px solid #999;padding:.2rem .8rem;color:#333}}
@media (prefers-color-scheme:dark){{body{{background:#111;color:#eee}}code,pre{{background:#222}}
th,td{{border-color:#333}}small,.note{{color:#bbb}}.ok{{color:#6ee7b7}}.bad{{color:#fca5a5}}}}
</style></head><body>
<h1>Omega GPU bench</h1>
<p>Run kernels whose machine code was written by Omega on your own NVIDIA GPU, check every output word
against a CPU reference, and put your card on this board. You need an NVIDIA driver, Python 3 and git.
No CUDA toolkit, no compiler, no pip install.</p>
<p class="note"><b>Kernels withdrawn.</b> The six v7 cubins and the cubin writer that produced them were
removed pending clean-room rewrite (CudaLicenseRisk Q6). Until it lands, <code>./run</code> reports NOT_RUN
on every GPU and writes no receipt. The rows below are kept unchanged as historical records; the kernels they
hash are withdrawn, and no new run of them is accepted.</p>
<pre>{cmd}</pre>
<p>Once the kit ships kernels again, it writes a receipt under <code>receipts/</code>. Open a pull request
with it to <a href="https://github.com/{repo}">github.com/{repo}</a>; CI checks it and, once merged, it shows
up here.</p>
<p class="note"><b>What runs where.</b> The withdrawn kernels were SASS assembled by Omega's <code>asm2</code>
from a hand-written listing and wrapped into a cubin. They reached the GPU through {path}. Receipts are
self-reported: CI checks the kernel hashes, counts, verdicts, every reported reference value (recomputed from
the public seed), the output hash of a clean run, and the GB/s arithmetic, but nobody re-ran your GPU. The
three seed rows are my own rentals on vast through OpenResearch on 2026-10-26, run before this kit existed;
they were not timed.</p>
<h2>Board</h2>
<table><thead><tr><th>#</th><th>GPU</th><th>Driver</th><th>Where</th><th>Origin</th><th>Kernels</th>
<th>vecadd speed (2<sup>26</sup> words)</th><th>Date</th><th>Receipt</th></tr></thead>
<tbody>
{rows}
</tbody></table>
<p><small>vecadd: c[i] = a[i] + b[i] on 2<sup>20</sup> + 7 words, every word compared. neg: the same kernel with one
register changed, which must be caught (NEG_DETECTED). Speed: median of 5 rounds of 20 launches timed with CUDA
events, 12 bytes moved per word. {nvalid} receipts shown, {nrej} rejected by the validator.</small></p>
{waiting}
<p><small>Source, rules and validator: <a href="https://github.com/{repo}">github.com/{repo}</a>.
Machine-readable: <a href="receipts.json">receipts.json</a>.</small></p>
</body></html>
"""

if __name__ == "__main__":
    main()
